import raw from './dev-snapshot.json'
import type { Clock, Diff, Plan, Timeline } from '../types'

/**
 * The dev routes' real output for the fallback scenario, with the clock on its last day. Generated by the
 * backend (`python -m billing_sim.cli snapshot`, checked by `backend/tests/test_snapshot.py`), so the dev page
 * tests render exactly the keys the API sends.
 */
export const snapshot = raw as unknown as { plan: Plan; timeline: Timeline; diff: Diff; clock: Clock }
